```mswea_bash_command
cat > /app/irc.py <<'PY'
import socket,threading,core
nicks=set()
nl=threading.Lock()
def serve(s):
    buf=''; token=None; nick=None; registered=False
    def out(x):
        try:s.sendall((x+'\r\n').encode())
        except:pass
    try:
        while True:
            z=s.recv(4096)
            if not z:return
            buf+=z.decode(errors='ignore')
            while '\r\n' in buf:
                line,buf=buf.split('\r\n',1); a=line.split(); cmd=a[0].upper() if a else ''
                if not cmd:continue
                if cmd=='PASS':
                    token=a[1] if len(a)>1 else None
                elif cmd=='NICK':
                    new=a[1] if len(a)>1 else ''
                    with nl: collision=new in nicks and new!=nick
                    if collision:
                        out(':huddle 433 '+new+' '+new+' :Nickname is already in use')
                    else:nick=new
                elif cmd=='USER':
                    valid=bool(token and core.uid(token))
                    if not valid:
                        out(':huddle 464 '+(nick or '*')+' :Password incorrect')
                    elif not registered:
                        with nl:nicks.add(nick or 'guest')
                        registered=True; nick=nick or 'guest'
                        for code in ('001','002','003','004','005','422'):
                            out(':huddle '+code+' '+nick+' :Welcome')
                elif cmd=='PING':
                    out('PONG '+(' '.join(a[1:]) if len(a)>1 else ''))
                elif cmd=='QUIT':
                    return
                elif cmd in ('PONG','MODE','WHO','LIST','NAMES','TOPIC','JOIN','PRIVMSG'):
                    if cmd=='JOIN' and len(a)>1:
                        out(':'+str(nick)+'!user@localhost JOIN '+a[1])
                else:
                    out(':huddle 421 '+(nick or '*')+' '+a[0]+' :Unknown command')
    finally:
        if registered:
            with nl:nicks.discard(nick)
        try:s.close()
        except:pass
def main():
    x=socket.socket();x.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);x.bind(('0.0.0.0',6667));x.listen()
    while True:
        s,_=x.accept();threading.Thread(target=serve,args=(s,),daemon=True).start()
main()
